-- Run in a transaction, optionally after the migration; never commits fixtures.
create temporary table qa_people(label text primary key,id uuid default gen_random_uuid());
insert into qa_people(label) values('sponsor'),('seller'),('other'),('agency'),('member'),('admin'),('level2');
grant select on qa_people to authenticated;
create function pg_temp.id(p text) returns uuid language sql as $$select id from qa_people where label=p$$;
create function pg_temp.login(p text) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(p),'role','authenticated')::text,true);end$$;
create function pg_temp.ok(p boolean,m text) returns void language plpgsql as $$begin if p is distinct from true then raise exception 'FAIL: %',m;end if;end$$;
insert into auth.users(id,email,email_confirmed_at,aud,role) select id,'recruit-qa-'||id||'@example.invalid',now(),'authenticated','authenticated' from qa_people;
insert into public.vp_accounts(user_id,email,full_name,status,role,sales_passed_at,sales_quiz_version) select id,'recruit-qa-'||id||'@example.invalid','Rollback recruitment QA',case when label='seller' then 'onboarding' else 'active' end,case when label in ('admin','agency') then label else 'vp' end,now()-interval '1 day','ajax-basics-v1' from qa_people;
update public.vp_accounts set agency_id=pg_temp.id('agency') where user_id=pg_temp.id('member');
update public.vp_settings set registration_open=true;
create temporary table qa_terms as select id from public.vp_terms where status='published' limit 1;
insert into public.vp_terms(version,title,body,status,content_hash) select 'rollback-'||gen_random_uuid(),'QA','QA only','published','qa' where not exists(select 1 from qa_terms);
insert into qa_terms select id from public.vp_terms where status='published' and not exists(select 1 from qa_terms);
grant select on qa_terms to authenticated;
insert into public.vp_documents(user_id,kind,path,mime,bytes) select pg_temp.id('seller'),k,gen_random_uuid()::text,'image/png',100 from unnest(array['portrait','trade_proof']) k;
create temporary table qa_link(token text);grant all on qa_link to authenticated;
set local role authenticated;
select pg_temp.login('sponsor');insert into qa_link select public.vp_recruitment_link();
select pg_temp.ok((select token=public.vp_recruitment_link() from qa_link),'persistent personal link');
select pg_temp.login('agency');
do $$begin begin perform public.vp_recruitment_link();raise exception 'FAIL agency';exception when insufficient_privilege then null;end;end$$;
select pg_temp.login('member');
do $$begin begin perform public.vp_recruitment_link();raise exception 'FAIL member';exception when insufficient_privilege then null;end;end$$;
select pg_temp.login('sponsor');
do $$begin begin perform public.vp_submit_application('{}',(select id from qa_terms),(select token from qa_link));raise exception 'FAIL self invite';exception when raise_exception then if sqlerrm='FAIL self invite' then raise;end if;end;end$$;
select pg_temp.login('seller');
select public.vp_submit_application('{"full_name":"QA Seller","street":"QA Straße 1","postal_code":"20095","city":"Hamburg","phone":"0000000000","clothing_size":"M","termsAccepted":true}',(select id from qa_terms),(select token from qa_link));
select pg_temp.login('other');
select public.vp_recruitment_link();
select pg_temp.login('seller');
reset role;
create temporary table qa_otherlink as select token from vp_private.recruitment_links where sponsor_id=pg_temp.id('other');grant select on qa_otherlink to authenticated;
set local role authenticated;
do $$begin begin perform public.vp_submit_application('{}',(select id from qa_terms),(select token from qa_otherlink));raise exception 'FAIL reassignment';exception when raise_exception then if sqlerrm='FAIL reassignment' then raise;end if;end;end$$;
reset role;
select pg_temp.ok((select sponsor_id=pg_temp.id('sponsor') from vp_private.recruits where user_id=pg_temp.id('seller')),'first application attribution');
update public.vp_accounts set status='active' where user_id=pg_temp.id('seller');
-- A second-level referral must not generate an upstream bonus.
insert into vp_private.recruits(user_id,sponsor_id) values(pg_temp.id('sponsor'),pg_temp.id('level2'));
create temporary table qa_order(id bigint);
with o as(insert into public.orders(stripe_session_id,stripe_event_id,status,amount_total,amount_tax,shipping_amount,currency,vp_id,test_mode,created_at) values('recruit-qa-'||gen_random_uuid(),'rollback','paid',119000,19000,0,'eur',(select referral_code from public.vp_accounts where user_id=pg_temp.id('seller')),false,clock_timestamp()) returning id) insert into qa_order select id from o;
grant select on qa_order to authenticated;
select pg_temp.ok((select count(*)=2 from public.vp_earnings where order_id=(select id from qa_order)),'exactly seller and direct sponsor');
select pg_temp.ok((select rate_bps=1500 and remaining_net_cents=100000 from public.vp_earnings where order_id=(select id from qa_order) and earning_kind='sale'),'seller keeps 15 percent');
select pg_temp.ok((select rate_bps=200 and remaining_net_cents=100000 and earner_id=pg_temp.id('sponsor') from public.vp_earnings where order_id=(select id from qa_order) and earning_kind='recruitment'),'2000 cents additional on 1000 EUR net');
update public.orders set stripe_event_id='rollback replay' where id=(select id from qa_order);
select pg_temp.ok((select count(*)=2 from public.vp_earnings where order_id=(select id from qa_order)),'webhook replay no duplicate');
set local role authenticated;
select pg_temp.login('other');select pg_temp.ok(jsonb_array_length(public.vp_recruitment_overview()->'partners')=0,'other partner sees no roster');
do $$begin begin select count(*) from vp_private.recruits;raise exception 'FAIL raw recruits';exception when insufficient_privilege then null;end;end$$;
select pg_temp.login('sponsor');
select pg_temp.ok(jsonb_array_length(public.vp_recruitment_overview()->'partners')=1,'own direct roster');
select pg_temp.ok((public.vp_recruitment_overview()->'bonuses'->0->>'bonusCents')::int=2000,'bonus visible');
select pg_temp.login('admin');
select public.vp_reconcile_earning((select id from public.vp_earnings where order_id=(select id from qa_order) and earning_kind='sale'),'eligible',50000,'Rollback partial refund evidence');
select pg_temp.ok((select bool_and(remaining_net_cents=50000 and status='eligible') from public.vp_earnings where order_id=(select id from qa_order)),'partial refund updates both');
reset role;
-- Simulate an already closed pair to exercise correction ledger rather than change existing periods.
update public.vp_settings set settlement_open=true;
update public.vp_earnings set closed=true,booked_net_cents=50000,booked_commission_cents=round(50000*rate_bps/10000.0),booked_earner_cents=round(50000*earner_rate_bps/10000.0),version=1 where order_id=(select id from qa_order);
set local role authenticated;select pg_temp.login('admin');
select public.vp_reconcile_earning((select id from public.vp_earnings where order_id=(select id from qa_order) and earning_kind='sale'),'cancelled',0,'Rollback complete refund evidence');
select pg_temp.ok((select bool_and(remaining_net_cents=0 and status='cancelled') from public.vp_earnings where order_id=(select id from qa_order)),'full refund updates both');
select pg_temp.ok((select count(*)=2 and sum(commission_cents)=-8500 from public.vp_finance_lines where earning_id in (select id from public.vp_earnings where order_id=(select id from qa_order))),'closed commission and bonus corrections');
reset role;
-- Agency affiliation disables future bonuses, even for previously recruited sellers.
update public.vp_accounts set agency_id=pg_temp.id('agency') where user_id=pg_temp.id('seller');
insert into public.orders(stripe_session_id,stripe_event_id,status,amount_total,amount_tax,shipping_amount,currency,vp_id,test_mode,created_at) values('recruit-qa-agency-'||gen_random_uuid(),'rollback','paid',11900,1900,0,'eur',(select referral_code from public.vp_accounts where user_id=pg_temp.id('seller')),false,clock_timestamp());
select pg_temp.ok((select count(*)=1 from public.vp_earnings where earning_kind='recruitment' and earner_id=pg_temp.id('sponsor')),'no bonus for agency seller');
select pg_temp.ok(not has_function_privilege('anon','public.vp_recruitment_link()','EXECUTE'),'no anonymous link generation');
select pg_temp.ok(not has_function_privilege('authenticated','vp_private.vp_submit_application(jsonb,uuid,text)','EXECUTE'),'no bypass of wrapper');
select 'Recruitment, agency exclusion, privacy, attribution, replay and refund assertions passed' as result;
